WITH cleaned AS (SELECT id, customer_id, account_type, balance, opened_date, status, TRIM(account_type) AS clean_account_type, COALESCE(status, 'N/A') AS resolved_status FROM accounts WHERE account_type = 'LOAN' AND status IS NOT NULL) SELECT *, ROW_NUMBER() OVER (ORDER BY balance, id) AS event_seq, DENSE_RANK() OVER (PARTITION BY account_type, status ORDER BY balance DESC NULLS FIRST) AS balance_dense_rank, SUM(balance) OVER (PARTITION BY account_type) AS account_type_sum_balance FROM cleaned;
